entries.syntax:
// The signature a JPEG XL container starts with: 0x0D0A870A
aligned(8) class JpegXLSignatureBox extends Box('JXL ') {
	unsigned int(32) signature;
}

// The level of the codestream, 5 or 10
aligned(8) class JpegXLLevelBox extends Box('jxll') {
	unsigned int(8) level;
}

// The codestream, whole
aligned(8) class JpegXLCodestreamBox extends Box('jxlc') {
	bit(8) data[];
}

// A part of the codestream: its index, the last part's with the top bit set
aligned(8) class JpegXLPartialCodestreamBox extends Box('jxlp') {
	unsigned int(1) is_last;
	unsigned int(31) index;
	bit(8) data[];
}

// What it takes to make the JPEG file a JPEG XL codestream was made of again, byte for byte
aligned(8) class JpegBitstreamReconstructionBox extends Box('jbrd') {
	bit(8) data[];
}

// The index of an animation's key frames (ISO/IEC 18181-2 9.3): of the frames indexed, the ticks a second is of (TNUM/TDEN), and of each frame its offset in the codestream from the frame before, its duration in ticks and the frames it stands for, varints
aligned(8) class JpegXLFrameIndexBox extends Box('jxli') {
	varint frame_count; // NF
	unsigned int(32) tick_numerator; // TNUM
	unsigned int(32) tick_denominator; // TDEN
	for (i = 0; i < frame_count; i++) {
		varint offset; // OFFi
		varint duration; // Ti
		varint frames; // Fi
	}
}

// Exif: where in it the TIFF header is, then the Exif
aligned(8) class ExifBox extends Box('Exif') {
	unsigned int(32) tiff_header_offset;
	bit(8) data[];
}

// XMP, a box of the file, not a full box as the XMLBox of a 'meta' is (JPEG 2000's XML box too)
aligned(8) class JpegXMLBox extends Box('xml ') {
	string data;
}

// A box compressed with Brotli: the type of the box it is, then that box's content, compressed
aligned(8) class BrotliCompressedBox extends Box('brob') {
	unsigned int(32) box_type;
	bit(8) data[];
}
